#!/usr/bin/env bash
set -euo pipefail

ROOT="$(pwd)"
SELF="$(basename "$0")"
TMP="$(mktemp -d)"
cleanup() { rm -rf "$TMP"; }
trap cleanup EXIT

PAYLOAD_LINE=$(awk '/^__VISHWAKARMAA_PAYLOAD_BELOW__$/ {print NR; exit}' "$0")
if [[ -z "${PAYLOAD_LINE:-}" ]]; then
  echo "ERROR: embedded project payload marker not found." >&2
  exit 1
fi

PAYLOAD_LINE=$((PAYLOAD_LINE + 1))
tail -n +"$PAYLOAD_LINE" "$0" | base64 -d > "$TMP/project.tar.gz"
tar -xzf "$TMP/project.tar.gz" -C "$ROOT"
rm -f "$ROOT/$SELF"

echo "Project Vishwakarmaa V64 imported successfully."
echo "Run: git add -A && git commit -m 'Import Project Vishwakarmaa V64' && git push origin main"
exit 0
__VISHWAKARMAA_PAYLOAD_BELOW__
